import{_ as p,a as t,l as e,s as r,t as s,u as o,v as i,w as l,x as n,y as c,b as h,c as m,d,e as _,f as S,g,h as u,i as b,j as D,k as f,m as q,n as k,o as C,p as P,q as x,r as N}from"./chunks/node-get-json-keys.BH5whZCT.js";import{_ as J,H as O,f as R,i as y}from"./chunks/framework.BIGTPeBz.js";const F=JSON.parse('{"title":"NS_DS_Commander 插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/plugins/ns-ds-commander.md","filePath":"zh/plugins/ns-ds-commander.md"}'),v={name:"zh/plugins/ns-ds-commander.md"};function I(E,a,T,j,A,G){return O(),R("div",null,[...a[0]||(a[0]=[y('<h1 id="ns-ds-commander-插件" tabindex="-1">NS_DS_Commander 插件 <a class="header-anchor" href="#ns-ds-commander-插件" aria-label="Permalink to &quot;NS_DS_Commander 插件&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>NS_DS_Commander 是一套专用服务器（DS）调度管理工具，提供主服务器、子服务器与 UE 客户端之间的匹配、房间管理、服务器状态监控与定时任务能力。</p><p><strong>主要特性：</strong></p><ul><li>主服务器负责区域、房间匹配与云服务器生命周期管理</li><li>子服务器负责本地 DS 进程管理与主从转发</li><li>UE 客户端蓝图节点完成匹配、连接、状态上报</li><li>支持定时任务（Cron）自动开房与释放</li><li>支持自定义字段数据上报</li></ul><p><strong>引擎版本要求：</strong> Unreal Engine 5.0+</p><h2 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h2><p><img src="'+p+'" alt="系统架构"></p><hr><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="获取子系统" tabindex="-1">获取子系统 <a class="header-anchor" href="#获取子系统" aria-label="Permalink to &quot;获取子系统&quot;">​</a></h3><p>所有客户端蓝图节点都通过 <code>NS_Matchmaking Subsystem</code> 调用。使用前请先获取该子系统实例。</p><p><img src="'+t+'" alt="获取子系统"></p><hr><h2 id="连接流程" tabindex="-1">连接流程 <a class="header-anchor" href="#连接流程" aria-label="Permalink to &quot;连接流程&quot;">​</a></h2><h3 id="客户端连接主服务器" tabindex="-1">客户端连接主服务器 <a class="header-anchor" href="#客户端连接主服务器" aria-label="Permalink to &quot;客户端连接主服务器&quot;">​</a></h3><p>客户端通过 WebSocket 连接主服务器，认证成功后即可进行匹配、获取房间列表等操作。</p><p><img src="'+e+'" alt="客户端连接流程"></p><hr><h3 id="ds-连接子服务器" tabindex="-1">DS 连接子服务器 <a class="header-anchor" href="#ds-连接子服务器" aria-label="Permalink to &quot;DS 连接子服务器&quot;">​</a></h3><p>专用服务器启动后连接本地子服务器，子服务器再与主服务器保持通信，完成注册与心跳。</p><p><img src="'+r+'" alt="DS 连接流程"></p><hr><h2 id="客户端节点" tabindex="-1">客户端节点 <a class="header-anchor" href="#客户端节点" aria-label="Permalink to &quot;客户端节点&quot;">​</a></h2><p>::: client Connect to Server</p><p>使用 WebSocket URL 与密码连接主服务器。这是客户端使用所有其他节点的前提。</p><p><img src="'+s+'" alt="连接服务器"></p><hr><p>:::</p><p>::: client Disconnect</p><p>断开与主服务器的连接。</p><p><img src="'+o+'" alt="断开连接"></p><hr><p>:::</p><p>::: client Is Connected</p><p>检查当前是否已连接主服务器。</p><p><img src="'+i+'" alt="是否已连接"></p><hr><p>:::</p><p>::: client In Lobby</p><p>标记当前客户端处于大厅状态。</p><p><img src="'+l+'" alt="在大厅"></p><hr><p>:::</p><p>::: client In Game</p><p>标记当前客户端处于游戏对局中状态。</p><p><img src="'+n+'" alt="在游戏中"></p><hr><p>:::</p><p>::: client Set Player Info</p><p>设置玩家自定义信息（如昵称、头像、段位等），供匹配与房间展示使用。</p><p><img src="'+c+'" alt="设置玩家信息"></p><hr><p>:::</p><p>::: client Send Chat Message</p><p>发送聊天消息到当前房间。</p><p><img src="'+h+'" alt="发送聊天消息"></p><hr><p>:::</p><p>::: client Send Custom Operate Reply</p><p>发送自定义操作回复，常用于服务端下发指令后的客户端响应。</p><p><img src="'+m+'" alt="发送自定义操作回复"></p><hr><p>:::</p><p>::: client Start Matchmaking</p><p>开始匹配，客户端向主服务器请求加入可用房间或在指定地区创建新房间。</p><p><img src="'+d+'" alt="开始匹配"></p><hr><p>:::</p><p>::: client Cancel Matchmaking</p><p>取消当前匹配请求。</p><p><img src="'+_+'" alt="取消匹配"></p><hr><p>:::</p><p>::: client Is Matchmaking</p><p>检查当前是否处于匹配中状态。</p><p><img src="'+S+'" alt="是否匹配中"></p><hr><p>:::</p><p>::: client Get Available Regions</p><p>通过回调异步获取可用地区列表。调用后插件会向主服务器实时请求最新列表，收到服务端返回后通过回调返回结果，同时更新本地缓存。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>OnComplete</td><td>回调</td><td><code>bSuccess</code>(Boolean) + <code>Regions</code>(String 数组)</td></tr></tbody></table><blockquote><p>未连接时会立即以 <code>bSuccess = false</code> 和空数组回调，不会发起网络请求；连接确认成功后插件会自动从服务端拉取一次地区列表更新缓存。</p></blockquote><p><img src="'+g+'" alt="获取可用地区"></p><hr><p>:::</p><p>::: client Create Server</p><p>在指定地区创建新的专用服务器房间。</p><p><img src="'+u+'" alt="创建服务器"></p><hr><p>:::</p><p>::: client Get Room List</p><p>获取房间列表，支持按地区、模式等条件筛选。</p><p><img src="'+b+'" alt="获取房间列表"></p><hr><p>:::</p><p>::: client Get Server Stats</p><p>获取服务器运行统计信息，如 CPU、内存、在线人数等。</p><p><img src="'+D+'" alt="获取服务器状态"></p><hr><p>:::</p><h2 id="ds-服务器节点" tabindex="-1">DS 服务器节点 <a class="header-anchor" href="#ds-服务器节点" aria-label="Permalink to &quot;DS 服务器节点&quot;">​</a></h2><p>以下节点运行在专用服务器（DS）端，用于与调度系统交互。</p><p>::: ds DS Connect to Child Server</p><p>DS 启动后连接本地子服务器。</p><p><img src="'+f+'" alt="DS 连接子服务器"></p><hr><p>:::</p><p>::: ds DS Close Room</p><p>关闭当前房间，通常在定时任务释放或管理员主动关闭时调用。</p><p><img src="'+q+'" alt="DS 关闭房间"></p><hr><p>:::</p><p>::: ds DS Set Room Joinable Status</p><p>设置房间是否允许新玩家加入。</p><p><img src="'+k+'" alt="DS 设置房间可加入状态"></p><hr><p>:::</p><p>::: ds DS Report Custom Fields Data</p><p>向调度系统上报自定义字段数据，可用于房间筛选与展示。</p><p><img src="'+C+'" alt="DS 上报自定义字段数据"></p><hr><p>:::</p><h2 id="json-工具节点" tabindex="-1">JSON 工具节点 <a class="header-anchor" href="#json-工具节点" aria-label="Permalink to &quot;JSON 工具节点&quot;">​</a></h2><p>::: json Extract Json Value</p><p>从 JSON 字符串中提取指定键的值。</p><p><img src="'+P+'" alt="提取 JSON 值"></p><hr><p>:::</p><p>::: json Get Json Keys</p><p>获取 JSON 对象中所有顶层键名。</p><p><img src="'+x+'" alt="获取 JSON 键"></p><hr><p>:::</p><p>::: json Json Has Key</p><p>检查 JSON 对象中是否包含指定键。</p><p><img src="'+N+'" alt="JSON 包含键"></p><hr><p>:::</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><strong>主服务器地址</strong> - 默认 WebSocket 端口为 8088，请确保防火墙放行。</li><li><strong>密码认证</strong> - 连接主服务器时需提供正确密码。</li><li><strong>DS 本地端口</strong> - DS 默认通过本地 8081 端口连接子服务器。</li><li><strong>定时任务</strong> - 通过 Web 管理端或 REST API 配置，到期前会提前通知 DS 释放。</li><li><strong>自定义字段</strong> - 使用 <code>Report Custom Fields Data</code> 上报的字段可用于房间列表筛选。</li></ol><h2 id="技术支持" tabindex="-1">技术支持 <a class="header-anchor" href="#技术支持" aria-label="Permalink to &quot;技术支持&quot;">​</a></h2><ul><li>插件作者：NodeSmith</li><li>Fab商店：com.epicgames.launcher://ue/Fab/product79aa810c-f7a0-4582-b257-287d7f42aefe</li></ul>',143)])])}const V=J(v,[["render",I]]);export{F as __pageData,V as default};
